"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["21878"],{51660(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.nao_encontrado","status":404,"titulo":"Valor de dom\xednio n\xe3o encontrado neste fato"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.nao_encontrado","requisitos":[],"oQueAconteceu":["O `{codigo}` da rota n\xe3o corresponde a nenhum valor do fato. Isso vale para a corre\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}`), para a desativa\xe7\xe3o (`DELETE` na mesma rota) e para a reativa\xe7\xe3o (`POST /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}/ativacao`). O c\xf3digo \xe9 procurado depois de aparado dos espa\xe7os nas pontas, e mai\xfasculas e min\xfasculas contam: `eja` n\xe3o \xe9 o valor `EJA`. O valor desativado continua no fato, ent\xe3o ele n\xe3o gera esta resposta.","Na corre\xe7\xe3o, a busca do valor vem antes da confer\xeancia do corpo: com um c\xf3digo que n\xe3o existe, a resposta \xe9 esta, mesmo que a descri\xe7\xe3o ou a orienta\xe7\xe3o enviadas tamb\xe9m tivessem problemas. A busca do fato vem antes de tudo (`uniplus.configuracao.fato_candidato.nao_encontrado`), seguida da recusa de fato de sistema (`uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada`). Na corre\xe7\xe3o, v\xeam ainda as recusas de fato sem valores pr\xf3prios (`uniplus.configuracao.fato_valor_dominio.nao_permitido_fora_de_categorico`, `uniplus.configuracao.fato_candidato.agregado_nao_tem_valores_proprios`, porque os valores do resumo de grupo s\xe3o os do fato de membro e s\xe3o mantidos nele, e `uniplus.configuracao.fato_valor_dominio.nao_permitido_fora_de_fonte_global`). S\xf3 depois disso o c\xf3digo do valor \xe9 procurado. Na desativa\xe7\xe3o e na reativa\xe7\xe3o essas tr\xeas confer\xeancias n\xe3o rodam: num fato que resume respostas de grupo, que n\xe3o tem valores pr\xf3prios, o c\xf3digo do valor n\xe3o \xe9 encontrado e a resposta \xe9 esta."],"comoResolver":["Confira o c\xf3digo do valor no fato, respeitando as mai\xfasculas e min\xfasculas. Se o valor nunca foi cadastrado, acrescente-o (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`). O c\xf3digo de um valor n\xe3o \xe9 editado nem removido; mudar o sentido de uma op\xe7\xe3o \xe9 acrescentar outro valor e desativar o antigo (UNI-REQ-0159)."],"ondeAparece":["Corre\xe7\xe3o de um valor de um fato do cat\xe1logo, com c\xf3digo que n\xe3o resolve","Desativa\xe7\xe3o de um valor de um fato do cat\xe1logo, com c\xf3digo que n\xe3o resolve","Reativa\xe7\xe3o de um valor de um fato do cat\xe1logo, com c\xf3digo que n\xe3o resolve"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);